public double price(int qty) { return new PriceCalculator(this, qty).compute(); }

private static final class PriceCalculator {
    private final Order order; private final int qty;
    private double discount;

    PriceCalculator(Order order, int qty) { this.order = order; this.qty = qty; }
    double compute() { applyDiscount(); return order.base() * qty * (1 - discount); }
    private void applyDiscount() { if (qty > 100) discount = 0.05; }
}

